    var next = ids.reduce(function (m, id) { return Math.min(m, P.fam.disp[id].end); }, Infinity);
    var sum = (ids.length ? '파견 ' + ids.length + (isFinite(next) ? ' · 다음 귀환 ' + clock(next) : '') : '') + (idle ? (ids.length ? ' · ' : '') + '대기 ' + idle : '');
