  ACT.skylook = function () { act('skyLook').then(function (r) { if (!r) return; Snd.play('spirit'); toast(R.josa(r.name, '을', '를') + ' 올려다봤습니다', '별조각 +' + r.shard + ' · 마나 +' + fmt(r.mana), 2600); render(); }); };
