    if (mode !== 'solo') { S.confirm.twreal = 0; API.towerOp({ mode: 'ready', kind: mode, on: true }).then(function (j) { if (j.error) { toast('별의 탑', j.error); return; } S.towerAt = 0; loadTower(); }); return; }
